// 회원 전체 조회 쿼리문
SELECT E.EMP_ID, E.EMP_NAME, E.EMAIL, E.PHONE, D.DEPT_TITLE AS DEPT_NAME, J.JOB_NAME, E.SALARY, E.ENT_YN FROM EMPLOYEE E LEFT JOIN DEPARTMENT D ON E.DEPT_CODE = D.DEPT_ID LEFT JOIN JOB J ON E.JOB_CODE = J.JOB_CODE ORDER BY E.EMP_ID ASC
// 회원 정보 수정 쿼리문
SELECT * FROM EMPLOYEE WHERE EMP_ID = ?
UPDATE EMPLOYEE SET EMAIL = ?, PHONE = ?, DEPT_CODE = ?, JOB_CODE = ?, SALARY = ?, HIRE_DATE = ?, ENT_YN = ? WHERE EMP_ID = ?
SELECT E.EMP_ID, E.EMP_NAME, E.EMAIL, E.PHONE, D.DEPT_TITLE AS DEPT_NAME, J.JOB_NAME, E.SALARY, E.ENT_YN FROM EMPLOYEE E LEFT JOIN DEPARTMENT D ON E.DEPT_CODE = D.DEPT_ID LEFT JOIN JOB J ON E.JOB_CODE = J.JOB_CODE WHERE E.EMP_ID = ?
